"""Palindrome Partitioning — cut after every palindromic prefix.

Time: O(n * 2^n)   Space: O(n)
"""
from typing import List


class Solution:
    def partition(self, s: str) -> List[List[str]]:
        out, path = [], []

        def walk(start: int) -> None:
            if start == len(s):
                out.append(path[:])
                return
            for end in range(start + 1, len(s) + 1):
                piece = s[start:end]
                if piece == piece[::-1]:
                    path.append(piece)
                    walk(end)
                    path.pop()

        walk(0)
        return out
